import numpy as np
def f3(z):
    return z**3 - 81*z**2 + 54

# Test integer divisors of 54 that are >= 3: {3, 6, 9, 18, 27, 54}
candidates = [3, 6, 9, 18, 27, 54]
for z in candidates:
    if f3(z) == 0:
        print(f"Solution found at z={z}")
    else:
        print(f"f3({z}) = {f3(z)}")
